#include <windows.h>
#include <stdio.h>

/*
 * DLL Injection Steps (OAWC):
 * 1. OpenProcess - Get handle to target
 * 2. VirtualAllocEx - Allocate memory in target
 * 3. WriteProcessMemory - Write DLL path
 * 4. CreateRemoteThread - Execute LoadLibrary
 */

BOOL InjectDll(DWORD processId, const char* dllPath) {
    HANDLE hProcess = NULL;
    LPVOID remoteBuf = NULL;
    HANDLE hThread = NULL;
    BOOL success = FALSE;

    // Step 1: Open target process
    hProcess = OpenProcess(
        PROCESS_CREATE_THREAD |  // CreateRemoteThread
        PROCESS_VM_OPERATION |    // VirtualAllocEx/VirtualFreeEx
        PROCESS_VM_WRITE,          // WriteProcessMemory
        FALSE,
        processId
    );

    if (!hProcess) {
        printf("[-] OpenProcess failed: %d\n", GetLastError());
        return FALSE;
    }
    printf("[+] Opened process %d\n", processId);

    // Step 2: Allocate memory in target process
    SIZE_T dllPathLen = strlen(dllPath) + 1;
    remoteBuf = VirtualAllocEx(
        hProcess,
        NULL,
        dllPathLen,
        MEM_COMMIT | MEM_RESERVE,
        PAGE_READWRITE
    );

    if (!remoteBuf) {
        printf("[-] VirtualAllocEx failed: %d\n", GetLastError());
        goto cleanup;
    }
    printf("[+] Allocated memory at %p\n", remoteBuf);

    // Step 3: Write DLL path to target process
    if (!WriteProcessMemory(
        hProcess,
        remoteBuf,
        dllPath,
        dllPathLen,
        NULL
    )) {
        printf("[-] WriteProcessMemory failed: %d\n", GetLastError());
        goto cleanup;
    }
    printf("[+] Wrote DLL path to target\n");

    // Step 4: Create remote thread to load DLL
    HMODULE hKernel32 = GetModuleHandleA("kernel32.dll");
    LPVOID loadLibraryAddr = (LPVOID)GetProcAddress(
        hKernel32, "LoadLibraryA"
    );

    hThread = CreateRemoteThread(
        hProcess,
        NULL,
        0,
        (LPTHREAD_START_ROUTINE)loadLibraryAddr,
        remoteBuf,
        0,
        NULL
    );

    if (!hThread) {
        printf("[-] CreateRemoteThread failed: %d\n", GetLastError());
        goto cleanup;
    }
    printf("[+] Remote thread created successfully\n");
    success = TRUE;

cleanup:
    if (hThread) CloseHandle(hThread);
    // Note: Don't free remoteBuf - the DLL needs this path
    if (hProcess) CloseHandle(hProcess);
    return success;
}
