import psutil
from collections import defaultdict

def detect_suspicious_injections():
    """Check for common injection indicators."""
    suspicious = []

    for proc in psutil.process_iter(['pid', 'name', 'memory_info']):
        try:
            # Check 1: Processes with unusual loaded modules
            # (DLLs not from system32 or program files)
            suspicious_dlls = []
            for dll in proc.memory_maps():
                path = dll.path.lower()
                if not any(x in path for x in ['windows\\system32', 
                                                 'windows\\syswow64',
                                                 'program files']):
                    if not path.startswith('\\'):  # Skip shared sections
                        suspicious_dlls.append(path)

            if suspicious_dlls:
                suspicious.append({
                    'pid': proc.info['pid'],
                    'name': proc.info['name'],
                    'indicator': 'unusual_dlls',
                    'details': suspicious_dlls[:5]  # Top 5
                })

        except (psutil.AccessDenied, psutil.NoSuchProcess):
            continue

    return suspicious

# Note: Real detection requires ETW, kernel callbacks,
